examples.code:
class Coordenada:
    def __init__(self, x, y):
        self.x = x
        self.y = y

    def __str__(self):
        return f"Punto({self.x}, {self.y})"

    def __repr__(self):
        return f"Coordenada(x={self.x}, y={self.y})"

p = Coordenada(10, 20)
print("Para usuario:", str(p))
print("Para depurador:", repr(p))

